/**
 * search_docs tool — keyword search across all doc sections.
 */
import { z } from 'zod';
export const searchDocsSchema = z.object({
    query: z.string().max(500).describe('Search query — keywords to match against documentation sections'),
});
export function handleSearchDocs(input, index) {
    const results = index.search(input.query, 5);
    if (results.length === 0) {
        return `No documentation sections matched "${input.query}". Try different keywords.`;
    }
    const lines = results.map((r, i) => `${i + 1}. **${r.title}** (${r.sourceFile}, score: ${r.score})\n   ${r.preview}${r.preview.length >= 300 ? '...' : ''}`);
    return `Found ${results.length} matching sections:\n\n${lines.join('\n\n')}`;
}
